package io.github.qiangjian.connect;

import android.app.Service;
import android.content.Intent;
import io.github.libxposed.api.XposedInterface.HookHandle;
import io.github.libxposed.api.XposedModule;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.List;

/** Guards only the real launcher clicks generated by OplusRelayDirectory. Ordinary OEM clicks are untouched. */
final class OplusRelayClickAdapter implements AutoCloseable {
    private record Click(Object service, AppRelayPeer peer) {}
    private final XposedModule module;
    private final ClassLoader loader;
    private final AppRelayNativeDelegate delegate;
    private final List<HookHandle> hooks = new ArrayList<>();
    private final ThreadLocal<Click> active = new ThreadLocal<>();
    private volatile boolean closed;
    private final java.util.concurrent.ThreadPoolExecutor worker = new java.util.concurrent.ThreadPoolExecutor(1, 1, 0,
            java.util.concurrent.TimeUnit.SECONDS, new java.util.concurrent.ArrayBlockingQueue<>(8), r -> {
                Thread thread = new Thread(r, "qj-oplus-relay-click"); thread.setDaemon(true); return thread;
            });
    OplusRelayClickAdapter(XposedModule module, ClassLoader loader, AppRelayNativeDelegate delegate) {
        this.module = module; this.loader = loader; this.delegate = delegate;
    }
    void install() throws ReflectiveOperationException {
        Class<?> service = Class.forName("com.oplus.synergy.service.SynergyCoreService", false, loader);
        Class<?> config = Class.forName("com.oplus.synergy.utils.Config", false, loader);
        Class<?> link = Class.forName("com.oplus.synergy.linkmanager.LinkManager", false, loader);
        Method instance = link.getMethod("getInstance"), ready = link.getMethod("getONetInitFlag");
        String action = (String) config.getField("ACTION_APPLICATION_RELAY_SOURCE_CLICK").get(null);
        String type = (String) config.getField("KEY_RELAY_TYPE").get(null), remind = (String) config.getField("RELAY_EXTEND_KEY_REMIND_TYPE").get(null);
        try {
            hooks.add(module.hook(service.getDeclaredMethod("onStartCommand", Intent.class, int.class, int.class))
                    .setId("qj.oplus.relay.selected-click").intercept(chain -> {
                Intent intent = (Intent) chain.getArg(0);
                if (intent == null || !action.equals(intent.getAction()) || !delegate.isGatewayClick(intent)) return chain.proceed();
                if (closed) return Service.START_NOT_STICKY;
                AppRelayPeer peer = delegate.selectedClick(intent);
                if (peer == null || intent.getIntExtra(type, -1) != 1 || !Boolean.TRUE.equals(ready.invoke(instance.invoke(null))))
                    return Service.START_NOT_STICKY;
                // Remind=2 selects the current native request-sync path, not an unrelated old relay-later deep link.
                Intent copy = new Intent(intent).putExtra(remind, "2");
                Click previous = active.get(); active.set(new Click(chain.getThisObject(), peer));
                try { return chain.proceed(new Object[]{copy, chain.getArg(1), chain.getArg(2)}); }
                finally { if (previous == null) active.remove(); else active.set(previous); }
            }));
            hooks.add(module.hook(service.getDeclaredMethod("relayImmediateWrapper", int.class, String.class, String.class))
                    .setId("qj.oplus.relay.data-ready").intercept(chain -> {
                Click click = active.get();
                if (click == null || click.service != chain.getThisObject()) return chain.proceed();
                if (closed || !click.peer.equals(delegate.selected(click.peer.nativeId()))
                        || ((Integer) chain.getArg(0)) != 1 || !Boolean.TRUE.equals(ready.invoke(instance.invoke(null)))) return null;
                return chain.proceed();
            }));
            hooks.add(module.hook(service.getDeclaredMethod("startCastRelay", String.class))
                    .setId("qj.oplus.relay.no-mirage-fallback").intercept(chain -> {
                Click click = active.get();
                if (click != null && click.service == chain.getThisObject()) return null;
                return chain.proceed();
            }));
            hooks.add(module.hook(service.getDeclaredMethod("relayImmediate", int.class, String.class, String.class))
                    .setId("qj.oplus.relay.native-sync").intercept(chain -> {
                Click click = active.get();
                if (click == null || click.service != chain.getThisObject()) return chain.proceed();
                if (closed || ((Integer)chain.getArg(0)) != 1 || !click.peer.equals(delegate.selected(click.peer.nativeId()))) return null;
                String pkg = (String)chain.getArg(1);
                AppRelaySync.validate("native-click", pkg);
                AppRelayEvents.emit(AppRelayEvents.Event.NATIVE_CLICK, "oplus-click", AppRelayEvents.Outcome.PENDING);
                try { worker.execute(() -> {
                    try {
                        OplusRelayPermission.check((Service)click.service, loader, pkg);
                        if (closed || !click.peer.equals(delegate.selected(click.peer.nativeId()))) return;
                        delegate.requestSync(click.peer, pkg).whenComplete((result, error) -> {
                            if (result != null) AppRelayEvents.emit(AppRelayEvents.Event.NATIVE_CLICK_RESULT, result.requestId(), AppRelayEvents.outcome(result));
                            if (error != null || result == null || result.state() != AppRelayTasks.State.COMPLETED)
                                android.util.Log.w("QiangJianRelay", "native_sync_failed");
                        });
                    } catch (Exception unavailable) { android.util.Log.w("QiangJianRelay", "native_sync_unavailable"); }
                }); } catch (java.util.concurrent.RejectedExecutionException busy) { android.util.Log.w("QiangJianRelay", "native_sync_busy"); }
                // Confirmation/type8 are executed at the selected source, never on pubList.
                return null;
            }));
        } catch (ReflectiveOperationException | RuntimeException failure) { close(); throw failure; }
    }
    @Override public void close() { closed = true; for (HookHandle hook : hooks) hook.unhook(); hooks.clear(); worker.shutdown(); }
}
